from fractions import Fraction

def pi_str(c):
    # A multiple of pi, written the way you'd write it by hand
    if c == 1:
        return "π"
    if c.denominator == 1:
        return f"{c}π"
    return f"({c})π"

k = int(input())
for i in range(k):
    kind = input()
    value = Fraction(int(input()))
    if kind == "radius":
        r = value
    elif kind == "diameter":
        r = value / 2
    else:
        r = value / 2
    d = 2 * r
    c = 2 * r
    print(f"r = {r}, d = {d}, C = {pi_str(c)}")

from fractions import Fraction
import math

def pi_str(c):
    # A multiple of pi, written the way you'd write it by hand
    if c == 1:
        return "π"
    if c.denominator == 1:
        return f"{c}π"
    return f"({c})π"

k = int(input())
for i in range(k):
    kind = input()
    if kind == "ring":
        outer = int(input())
        inner = int(input())
        a = Fraction(outer * outer - inner * inner)
        print(f"ring A = {pi_str(a)}")
    else:
        value = int(input())
        if kind == "radius":
            r = Fraction(value)
        elif kind == "diameter":
            r = Fraction(value, 2)
        elif kind == "circumference":
            r = Fraction(value, 2)
        else:
            r = Fraction(math.isqrt(value))
        print(f"r = {r}, A = {pi_str(r * r)}")

