from fractions import Fraction

def radical(n):
    # The square root of a whole number n, simplified: radical(48) is "4√3"
    if n == 0:
        return "0"
    out = 1
    k = 2
    while k * k <= n:
        while n % (k * k) == 0:
            n = n // (k * k)
            out = out * k
        k = k + 1
    if n == 1:
        return f"{out}"
    if out == 1:
        return f"√{n}"
    return f"{out}√{n}"

k = int(input())
for i in range(k):
    kind = input()
    if kind == "inscribed":
        central = int(input())
        print(f"inscribed = {Fraction(central, 2)}°")
    else:
        r = int(input())
        x = int(input())
        if kind == "chord":
            n = 4 * (r * r - x * x)
        elif kind == "distance":
            n = r * r - (x // 2) * (x // 2)
        else:
            n = x * x - r * r
        print(f"{kind} = {radical(n)}")
